old = """  set res(_res: Response | undefined) {
    if (this.#res && _res) {
      _res = createResponseInstance(_res.body, _res)
      for (const [k, v] of this.#res.headers.entries()) {
        if (k === 'content-type') {
          continue
        }
        if (k === 'set-cookie') {
          // Merge cookies instead of replacing them: cookies set on the current
          // response (e.g. by middleware) must survive alongside cookies that
          // the new response (e.g. from a handler) brings with it.
          const cookies = this.#res.headers.getSetCookie()
          const newCookies = _res.headers.getSetCookie()
          _res.headers.delete('set-cookie')
          for (const cookie of cookies) {
            _res.headers.append('set-cookie', cookie)
          }
          for (const cookie of newCookies) {
            if (!cookies.includes(cookie)) {
              _res.headers.append('set-cookie', cookie)
            }
          }
        } else {
          _res.headers.set(k, v)
        }
      }
    }
    this.#res = _res
    this.finalized = true
  }
"""
new = """  set res(_res: Response | undefined) {
    if (_res) {
      const contextHeaders = this.#res?.headers ?? this.#preparedHeaders
      if (contextHeaders) {
        const contextCookies = contextHeaders.getSetCookie()
        _res = createResponseInstance(_res.body, _res)
        for (const [k, v] of contextHeaders.entries()) {
          if (k === 'content-type' || k === 'set-cookie') {
            continue
          }
          _res.headers.set(k, v)
        }
        if (contextCookies.length) {
          // Keep the context's Set-Cookie headers first, then append the new
          // Response's Set-Cookie headers that are not already present. This
          // preserves cookies from both sides (e.g. a cookie set by middleware
          // and one returned by a handler) without duplicating cookies that a
          // Context response method has already copied over.
          const responseCookies = _res.headers.getSetCookie()
          _res.headers.delete('set-cookie')
          for (const cookie of contextCookies) {
            _res.headers.append('set-cookie', cookie)
          }
          for (const cookie of responseCookies) {
            if (!contextCookies.includes(cookie)) {
              _res.headers.append('set-cookie', cookie)
            }
          }
        }
      }
    } else {
      this.#preparedHeaders = undefined
    }
    this.#res = _res
    this.finalized = true
  }
"""
assert old in s
p.write_text(s.replace(old, new))
print('setter patched')
